const log = $input.first().json;

const userPrompt = `Tu es un ingénieur SRE expert en monitoring.
Un log CRITICAL a été détecté dans le service "${log.source_id}".
Log : ${log.message}
Catégorie : ${log.category || 'SYSTEM'}
Historique récent :
${JSON.stringify(log.recent_logs || [])}

Réponds UNIQUEMENT en JSON valide, sans texte avant ou après :
{
  "cause_probable": "...",
  "actions_immediates": ["action 1", "action 2", "action 3"],
  "escalade_si": "...",
  "severite_estimee": "HIGH"
}
Maximum 150 mots.`;

return [{
  json: {
    ...log,
    llm_payload: {
      model: $env.GROQ_MODEL ?? 'llama-3.1-8b-instant',
      messages: [{ role: 'user', content: userPrompt }],
      max_tokens: 300,
      temperature: 0.3,
      response_format: { type: "json_object" }
    }
  }
}];

const log = $('Build LLM Prompt').first().json;

const staticFallbacks = {
  SECURITY:     'Vérifier les logs d\'accès, bloquer l\'IP source, notifier l\'équipe sécurité.',
  PERFORMANCE:  'Vérifier CPU/RAM/disque, identifier le processus fautif, redémarrer si nécessaire.',
  AVAILABILITY: 'Vérifier la connectivité réseau, l\'état du service et de ses dépendances.',
  DATA:         'Vérifier l\'intégrité des données, stopper les écritures, alerter l\'équipe DBA.',
  NETWORK:      'Vérifier la connectivité, les règles firewall, et les DNS.',
  SYSTEM:       'Vérifier les ressources système, les logs kernel, et l\'espace disque.'
};

function staticResponse(category) {
  return {
    cause_probable:     'LLM indisponible — réponse statique',
    actions_immediates: [staticFallbacks[category] || 'Analyser les logs et escalader.'],
    escalade_si:        'Si le problème persiste plus de 10 minutes',
    severite_estimee:   'CRITICAL',
    llm_source:         'static'
  };
}

// $json ici = réponse du HTTP Request node (ou objet erreur si "Continue on Fail")
const httpResult = $json;

// Si le nœud HTTP a échoué, $json contiendra un champ "error"
if (httpResult.error || !httpResult.choices) {
  return [{ json: { ...log, ...staticResponse(log.category) } }];
}

try {
  const rawText  = httpResult.choices[0].message.content.trim();
  const parsed   = JSON.parse(rawText);

  return [{
    json: {
      ...log,
      cause_probable:     parsed.cause_probable,
      actions_immediates: parsed.actions_immediates,
      escalade_si:        parsed.escalade_si,
      severite_estimee:   parsed.severite_estimee,
      llm_source:         'groq'
    }
  }];
} catch (e) {
  return [{ json: { ...log, ...staticResponse(log.category) } }];
}
